  }
  @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'YurtMenü',theme:makeTheme(dark),home:MenuHome(prefs:widget.prefs,dark:dark,onTheme:(v){setState(()=>dark=v);widget.prefs.setBool('dark',v);}));
